/// <reference types="vite/client" />

declare module '*&q=80' {
    const content: string;
    export default content;
}

declare module '*&w=128' {
    const content: string;
    export default content;
}

declare module '*?format=webp&w=128&q=80' {
    const content: string;
    export default content;
}

declare module '*?w=64&format=webp' {
    const content: string;
    export default content;
}

declare module '*&format=webp' {
    const content: string;
    export default content;
}

declare module '*?format=webp' {
    const content: string;
    export default content;
}
